import{_ as e,o,c as a,a2 as r}from"./chunks/framework.fsES6ZMC.js";const h=JSON.parse('{"title":"第 29 章 毕业项目 — 生产级 AI 推理平台的完整搭建","description":"","frontmatter":{},"headers":[],"relativePath":"29-毕业项目-生产级AI推理平台.md","filePath":"29-毕业项目-生产级AI推理平台.md"}'),d={name:"29-毕业项目-生产级AI推理平台.md"};function l(i,t,s,n,c,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第-29-章-毕业项目-—-生产级-ai-推理平台的完整搭建" tabindex="-1">第 29 章 毕业项目 — 生产级 AI 推理平台的完整搭建 <a class="header-anchor" href="#第-29-章-毕业项目-—-生产级-ai-推理平台的完整搭建" aria-label="Permalink to &quot;第 29 章 毕业项目 — 生产级 AI 推理平台的完整搭建&quot;">​</a></h1><blockquote><p>本章是全书的 capstone：把前 28 章串成一个可以写进简历的真实项目——&quot;在 kind 上从零搭一个具备安全基线、自动扩缩、灰度发布、成本可观测的 AI 推理平台&quot;。做完它，你在面试里讲的每个组件都有动手痕迹。</p></blockquote><h2 id="_29-1-项目规格-需求即考点" tabindex="-1">29.1 项目规格（需求即考点） <a class="header-anchor" href="#_29-1-项目规格-需求即考点" aria-label="Permalink to &quot;29.1 项目规格（需求即考点）&quot;">​</a></h2><p>目标：部署第 14 章的 embedding 服务（或任意模型服务），但这次按生产标准：</p><table tabindex="0"><thead><tr><th>需求</th><th>考点章节</th><th>验收标准</th></tr></thead><tbody><tr><td>入口用 Gateway API，业务路由与网关分权</td><td>16</td><td>HTTPRoute 在业务 ns，Gateway 在平台 ns</td></tr><tr><td>服务具备 PDB + 优雅终止 + 探针</td><td>10,3</td><td>滚动发布零失败请求（压测中）</td></tr><tr><td>自动扩缩容（HPA 基于 CPU+自定义指标）</td><td>11,12</td><td>压测 1→3 副本，负载停后回落</td></tr><tr><td>Pod Security restricted + SA 不挂 token</td><td>20</td><td>enforce=restricted 下运行；Pod 内无 SA token</td></tr><tr><td>NetworkPolicy 默认拒绝+最小放行（含 DNS）</td><td>22</td><td>deny-all 下服务仍全通（白名单正确）</td></tr><tr><td>GitOps 化：ArgoCD 管理+selfHeal</td><td>24</td><td>kubectl 手改被自动还原</td></tr><tr><td>成本可见：OpenCost 分摊到 ns</td><td>21</td><td>API 查询返回 ns 成本</td></tr><tr><td>金丝雀发布带指标门禁</td><td>24</td><td>镜像变更按 20%/50% 步进</td></tr><tr><td>全程有 Prometheus/Grafana 指标</td><td>12</td><td>Grafana 能看到延迟/副本数曲线</td></tr></tbody></table><h2 id="_29-2-实施路径-8-步-约-2-3-小时" tabindex="-1">29.2 实施路径（8 步，约 2-3 小时） <a class="header-anchor" href="#_29-2-实施路径-8-步-约-2-3-小时" aria-label="Permalink to &quot;29.2 实施路径（8 步，约 2-3 小时）&quot;">​</a></h2><p>前置：第 14 章的 kind 集群与容器镜像（<code>kind load docker-image</code> 已完成）。每步的详细命令都在对应章节 lab 里，这里给串联与顺序——<strong>顺序本身就是考点</strong>（先安全基线再上业务，先观测再调自动扩缩）。</p><p><strong>Step 1 平台底座</strong>（第 12 章）：helm 装 kube-prometheus-stack，确认 Prometheus/Grafana 活着。没有观测先上业务=盲飞。</p><p><strong>Step 2 安全基线</strong>（第 20/22 章）：</p><ul><li>建 ns <code>ai-prod</code>，打 <code>pod-security.kubernetes.io/enforce=restricted</code>。</li><li>default-deny ingress+egress NetworkPolicy + 放行 DNS + 放行网关到服务的 80。</li><li>验收：先空跑（用 busybox Pod 测白名单语义），再上业务。</li></ul><p><strong>Step 3 网关</strong>（第 16 章）：平台 ns 装 Envoy Gateway，建 Gateway（80，allowedRoutes 选 <code>ai-prod</code>）；业务侧 HTTPRoute 指向推理服务。验收：<code>status.parents</code> Accepted=True。</p><p><strong>Step 4 业务部署</strong>（第 3/10 章）：</p><ul><li>Deployment：readiness/liveness 探针、<code>terminationGracePeriodSeconds: 30</code>、preStop sleep 5、securityContext 全套（runAsNonRoot、drop ALL、seccomp RuntimeDefault）。</li><li>PDB：minAvailable 1。</li><li>SA：automountServiceAccountToken=false。</li><li>资源：requests 按 P95 估（第 21 章方法），先粗配后校准。</li></ul><p><strong>Step 5 弹性</strong>（第 11 章）：metrics-server + HPA（CPU 60%，min1 max4）。</p><p><strong>Step 6 观测补齐</strong>（第 12 章）：ServiceMonitor 让业务进 Prometheus；Grafana 建一个看板：QPS/P95 延迟/副本数/重启数四条曲线。</p><p><strong>Step 7 GitOps 化</strong>（第 24 章）：把以上全部清单推到一个 Git 仓库（lab 可用本地目录+ArgoCD 指向，或用 Gitea 起个仓），ArgoCD Application auto+sync+selfHeal。验收：<code>kubectl scale --replicas=3</code> 手改，30 秒内被还原。</p><p><strong>Step 8 终验（三连演练）</strong>：</p><ol><li><strong>压测扩缩</strong>：8 并发持续压（第 14 章坑：burst 打不进采样窗口），看副本 1→N→回落。</li><li><strong>滚动零损</strong>：压测进行中改镜像 tag rollout，统计失败数，预期个位数（第 10 章 lab 手法）。</li><li><strong>自愈/门禁</strong>：删一个 Pod（PDB 保证可用）；手改被 ArgoCD 还原。</li></ol><h2 id="_29-3-简历怎么写这个项目-示例-数字换成你的实测" tabindex="-1">29.3 简历怎么写这个项目（示例，数字换成你的实测） <a class="header-anchor" href="#_29-3-简历怎么写这个项目-示例-数字换成你的实测" aria-label="Permalink to &quot;29.3 简历怎么写这个项目（示例，数字换成你的实测）&quot;">​</a></h2><blockquote><p>在 kind 集群上从零构建生产标准的多租户 AI 推理平台：Gateway API 分权入口（平台/业务命名空间隔离）、Pod Security restricted 基线、NetworkPolicy 默认拒绝白名单放行、HPA 自动扩缩（实测压测 1→3 副本、负载后回落）、PDB+preStop 实现压测下滚动发布零失败请求、ArgoCD GitOps selfHeal 管理（手改配置 30s 内自动还原）、OpenCost 命名空间级成本分摊。熟悉从安全基线→观测→弹性→发布门禁的平台工程全链路。</p></blockquote><p>每个分句都对应一个可追问的实操细节，不怕深挖——这就是&quot;动手痕迹&quot;的意思。</p><h2 id="_29-4-常见失败与回退" tabindex="-1">29.4 常见失败与回退 <a class="header-anchor" href="#_29-4-常见失败与回退" aria-label="Permalink to &quot;29.4 常见失败与回退&quot;">​</a></h2><ul><li>Gateway 的 allowedRoutes 不通：回第 16 章第 9 步（ns label + status.parents 条件码）。</li><li>restricted 下镜像起不来：八成是 uid=0 或缺 seccomp 字段，看 event 里的违规项。</li><li>deny-all 后服务不通：99% 是 DNS 没放行（第 22 章第 5 步）。</li><li>HPA 无反应：URL 是否 FQDN+端口、是否持续压测（第 14 章三连坑）。</li><li>ArgoCD 不同步：app-of-apps 路径/权限，看 Application 的 sync 状态与事件。</li></ul><h2 id="_29-5-自测清单" tabindex="-1">29.5 自测清单 <a class="header-anchor" href="#_29-5-自测清单" aria-label="Permalink to &quot;29.5 自测清单&quot;">​</a></h2><ul><li>[ ] 9 项验收全绿（逐条打勾，不凭感觉）</li><li>[ ] 三连演练各留一次记录（截图/命令输出）</li><li>[ ] 简历段落已按实测数字改写</li><li>[ ] 能对着集群回答&quot;每层为什么这么配&quot;的 why 问题（不是 only how）</li></ul><blockquote><p>调研粮备注：本章为综合实操章，所有子步骤命令见对应章节 lab；依赖第 14 章环境。</p></blockquote>',26)])])}const _=e(d,[["render",l]]);export{h as __pageData,_ as default};
